2423	/**
2424	 * @brief 从当前位置起，沿剖面累计剩余爬升（米）。
2425	 * @param now_idx 当前采样点下标。
2426	 * @return 剩余上升米数；剖面不足两点则 -1。
2427	 */
2428	static int32_t helm_climb_remain_from_eles(uint32_t now_idx)
2429	{
2430	    uint32_t i;
2431	    int32_t gain = 0;
2432	
2433	    if (s_sh.climb_n < 2u) {
2434	        return -1;
2435	    }
2436	    for (i = now_idx; i + 1u < s_sh.climb_n; i++) {
2437	        const int16_t a = s_climb_eles[i];
2438	        const int16_t b = s_climb_eles[i + 1u];
2439	
2440	        if (a == (int16_t)VGRF_ELE_UNKNOWN || b == (int16_t)VGRF_ELE_UNKNOWN) {
2441	            continue;
2442	        }
2443	        if (b > a) {
2444	            gain += (int32_t)b - (int32_t)a;
2445	        }
2446	    }
2447	    return gain;
2448	}
