2450	/**
2451	 * @brief 按相邻采样点高差与水平步长，把该段归入平坦 / 中等 / 陡。
2452	 * @param e0 段起点海拔（米）。
2453	 * @param e1 段终点海拔（米）。
2454	 * @param step_cm 该段水平距离（厘米）；剖面按总里程均分。
2455	 * @return 0 平坦，1 中等，2 陡。上坡下坡都用 |高差|，档位直接跳、不插值。
2456	 *
2457	 * @note 只在 `helm_climb_profile_reload()` 换路线时调用，骑行中不重算。
2458	 */
2459	static uint8_t helm_climb_grade_zone(int16_t e0, int16_t e1, uint32_t step_cm)
2460	{
2461	    uint32_t de;
2462	    uint32_t g;
2463	
2464	    if (step_cm < 1u) {
2465	        return 0;
2466	    }
2467	    de = (e1 >= e0) ? (uint32_t)((int32_t)e1 - (int32_t)e0)
2468	                    : (uint32_t)((int32_t)e0 - (int32_t)e1);
2469	    /* 坡度% = |Δh|m / 步长m × 100 = de × 10000 / step_cm */
2470	    g = (de * 10000u) / step_cm;
2471	    if (g < HELM_CLIMB_GRADE_FLAT) {
2472	        return 0;
2473	    }
2474	    if (g < HELM_CLIMB_GRADE_STEEP) {
2475	        return 1;
2476	    }
2477	    return 2;
2478	}
