2512	/**
2513	 * @brief 判断剖面一段是否与当前脏区相交，避免竖线移动时提交整图三角形。
2514	 * @param clip LVGL 层裁剪区（绝对坐标）；NULL 视为全部可见。
2515	 * @param p1 段起点（屏坐标）。
2516	 * @param p2 段终点（屏坐标）。
2517	 * @param y_base 填充底边的 y。
2518	 * @param pad 线宽余量（像素），至少 2。
2519	 * @return true 需要提交绘制。
2520	 * @note 导航烘焙成功后 DRAW_TASK 已跳过；本函数只服务回退路径和「经过海拔」。
2521	 */
2522	static bool helm_climb_seg_in_clip(const lv_area_t * clip,
2523	    lv_point_precise_t p1, lv_point_precise_t p2, int32_t y_base, int32_t pad)
2524	{
2525	    int32_t x1;
2526	    int32_t x2;
2527	    int32_t y1;
2528	
2529	    if (clip == NULL) {
2530	        return true;
2531	    }
2532	    if (pad < 2) {
2533	        pad = 2;
2534	    }
2535	    x1 = (int32_t)(p1.x < p2.x ? p1.x : p2.x) - pad;
2536	    x2 = (int32_t)(p1.x > p2.x ? p1.x : p2.x) + pad;
2537	    y1 = (int32_t)(p1.y < p2.y ? p1.y : p2.y) - pad;
2538	    if (x2 < clip->x1 || x1 > clip->x2) {
2539	        return false;
2540	    }
2541	    if (y_base < clip->y1 || y1 > clip->y2) {
2542	        return false;
2543	    }
2544	    return true;
2545	}
