2557	static void helm_climb_paint_seg(lv_layer_t * layer, lv_point_precise_t p1,
2558	    lv_point_precise_t p2, int32_t y_base, lv_color_t fill, lv_color_t stroke,
2559	    int32_t lw)
2560	{
2561	    lv_draw_triangle_dsc_t tri;
2562	    lv_draw_line_dsc_t ld;
2563	
2564	    lv_draw_triangle_dsc_init(&tri);
2565	    tri.color = fill;
2566	    tri.opa = LV_OPA_COVER;
2567	    tri.grad.dir = LV_GRAD_DIR_NONE;
2568	    tri.p[0] = p1;
2569	    tri.p[1] = p2;
2570	    tri.p[2].x = p2.x;
2571	    tri.p[2].y = y_base;
2572	    lv_draw_triangle(layer, &tri);
2573	    tri.p[1].x = p2.x;
2574	    tri.p[1].y = y_base;
2575	    tri.p[2].x = p1.x;
2576	    tri.p[2].y = y_base;
2577	    lv_draw_triangle(layer, &tri);
2578	
2579	    lv_draw_line_dsc_init(&ld);
2580	    ld.color = stroke;
2581	    ld.width = lw > 0 ? lw : 2;
2582	    ld.opa = LV_OPA_COVER;
2583	    ld.round_start = 1;
2584	    ld.round_end = 1;
2585	    ld.p1 = p1;
2586	    ld.p2 = p2;
2587	    lv_draw_line(layer, &ld);
2588	}
