2656	    if (s_sh.climb_cursor == NULL || s_sh.climb_chart == NULL ||
2657	        s_sh.climb_ser == NULL || s_sh.climb_n < 2u) {
2658	        return;
2659	    }
2660	    lv_obj_update_layout(s_sh.climb_chart);
2661	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser,
2662	        (uint32_t)s_sh.climb_now, &p);
2663	
2664	    /* 指示器跟着**剖面点**：尖端贴在点**上方 2 px**（整个三角在剖面之上），
2665	     * 水平居中于该点 —— 也就是"下角指向灰绿交接处、高度在折线图上方"。
2666	     *
2667	     * ⚠⚠ 坐标约定（2026-09-25 踩过，别再"修"）：本页剖面有两条绘制路径 ——
2668	     * 现场 `helm_climb_draw_task()` 的填充、导航 `helm_climb_canvas_seg()` 的
2669	     * 烘焙 —— 都把 `lv_chart_get_point_pos_by_id()` 返回的**内容区坐标直接当
2670	     * 画布/盒坐标用**（不补图表自己的 pad）。指示器**必须沿用同一套**，
2671	     * 否则整条差一个 pad（pad_top = 22 px ⇒ 实测三角掉到折线下方、看着"位置全错"）。
2672	     * 真要统一，得两条绘制路径 + 指示器一起改，不能只挪指示器。 */
2673	    cw = lv_obj_get_width(s_sh.climb_chart);
2674	    chh = lv_obj_get_height(s_sh.climb_chart);
2675	    x = p.x - HELM_CLIMB_MARK_W / 2;
2676	    y = p.y - 2 - (HELM_CLIMB_MARK_H - 1);
2677	    if (x > cw - HELM_CLIMB_MARK_W && cw > HELM_CLIMB_MARK_W) {
2678	        x = cw - HELM_CLIMB_MARK_W;
2679	    }
2680	    if (x < 0) {
2681	        x = 0;
2682	    }
2683	    if (y > chh - HELM_CLIMB_MARK_H && chh > HELM_CLIMB_MARK_H) {
2684	        y = chh - HELM_CLIMB_MARK_H;
2685	    }
2686	    if (y < 0) {
2687	        y = 0;
2688	    }
2689	
2690	    /* 判断依据是"上次真的在屏上、且这一跳没超出相邻采样点该有的跨度"：
2691	     * 首帧、切页回来、suspend、换路线导致的大跳都直接 snap，别让游标
2692	     * 横穿整张剖面。translate 只是视觉偏移，不参与布局，也不碰 canvas。
2693	     *
2694	     * ⚠ 起点必须取**当前视觉位置**（set_pos + 正在跑的 translate），不能取上一次
2695	     * 目标位置：GNSS 采样可能比 220 ms 补间更快，取目标会在中途重启时把游标
2696	     * 甩到 "2×目标 − 新目标" 的位置上。 */
2697	    was_shown = !lv_obj_has_flag(s_sh.climb_cursor, LV_OBJ_FLAG_HIDDEN);
2698	    if (was_shown && s_cur_valid && !helm_anim_is_suspended()) {
2699	        int32_t cur_x = lv_obj_get_x(s_sh.climb_cursor) +
2700	                        lv_obj_get_style_translate_x(s_sh.climb_cursor, 0);
2701	        int32_t cur_y = lv_obj_get_y(s_sh.climb_cursor) +
2702	                        lv_obj_get_style_translate_y(s_sh.climb_cursor, 0);
2703	
2704	        if (LV_ABS(x - cur_x) <= 40 && LV_ABS(y - cur_y) <= 30) {
2705	            /* 对象先落新位，再用 translate 补回旧位置差 ⇒ 视觉上从当前位置滑过去。 */
2706	            dx = cur_x - x;
2707	            dy = cur_y - y;
2708	            lv_obj_set_pos(s_sh.climb_cursor, x, y);
2709	            lv_obj_set_style_translate_x(s_sh.climb_cursor, dx, 0);
2710	            lv_obj_set_style_translate_y(s_sh.climb_cursor, dy, 0);
2711	            helm_anim_run(s_sh.climb_cursor, helm_climb_cur_x_exec, dx, 0, 220,
2712	                          lv_anim_path_ease_out, helm_climb_cur_done);
2713	            helm_anim_run(s_sh.climb_cursor, helm_climb_cur_y_exec, dy, 0, 220,
2714	                          lv_anim_path_ease_out, helm_climb_cur_done);
2715	            goto placed;
2716	        }
2717	    }
2718	
2719	    helm_anim_stop(s_sh.climb_cursor, helm_climb_cur_x_exec);
2720	    helm_anim_stop(s_sh.climb_cursor, helm_climb_cur_y_exec);
2721	    lv_obj_set_pos(s_sh.climb_cursor, x, y);
2722	    lv_obj_set_style_translate_x(s_sh.climb_cursor, 0, 0);
2723	    lv_obj_set_style_translate_y(s_sh.climb_cursor, 0, 0);
2724	
2725	placed:
2726	    s_cur_valid = true;
2727	    lv_obj_clear_flag(s_sh.climb_cursor, LV_OBJ_FLAG_HIDDEN);
2728	}
