2730	/**
2731	 * @brief 按图表实际宽高分配/复用 RGB565 画布缓冲。
2732	 * @return 画布可用则为 true。
2733	 * @details 缓冲在 PSRAM。宽高未变则复用。分配失败返回 false，
2734	 *          调用方回退 `helm_climb_draw_task` 现场绘制。
2735	 */
2736	static bool helm_climb_canvas_ensure(void)
2737	{
2738	    int32_t w;
2739	    int32_t h;
2740	    size_t bytes;
2741	
2742	    if (s_sh.climb_canvas == NULL || s_sh.climb_chart == NULL) {
2743	        return false;
2744	    }
2745	    if (s_sh.climb) {
2746	        lv_obj_update_layout(s_sh.climb);
2747	    }
2748	    lv_obj_update_layout(s_sh.climb_chart);
2749	    w = lv_obj_get_width(s_sh.climb_chart);
2750	    h = lv_obj_get_height(s_sh.climb_chart);
2751	    if (w < 8 || h < 8) {
2752	        return false;
2753	    }
2754	    if (s_climb_cbuf != NULL && w == s_climb_cw && h == s_climb_ch) {
2755	        /*
2756	         * ⚠ 尺寸没变也**必须重新挂一次缓冲区**：画布对象可能刚被重建过（换主题 =
2757	         * `helm_shell_rebuild()` 删掉整棵 shell 再建），而 `s_climb_cbuf` 是我们自己的
2758	         * 内存、不属于 LVGL、重建不会动它 ⇒ 尺寸也恰好没变（同一个布局）⇒ 原来这里直接
2759	         * return，**新画布对象上从来没 set 过 buffer** ⇒ `lv_canvas_fill_bg()`/图层绘制
2760	         * 全落在空处，屏上只剩纸色底（用户 2026-09-27 深挖到的真因：数据/几何/可见性/烘焙
2761	         * 日志全都"正常"，就是没挂 buffer）。set_buffer 是幂等的，重复调用无副作用。
2762	         */
2763	        lv_canvas_set_buffer(s_sh.climb_canvas, s_climb_cbuf, w, h,
2764	            LV_COLOR_FORMAT_RGB565);
2765	        lv_obj_set_size(s_sh.climb_canvas, w, h);
2766	        syslog(LOG_NOTICE, "[climb] canvas buffer re-attached (reuse %dx%d)\n", (int)w, (int)h);
2767	        return true;
2768	    }
2769	    bytes = (size_t)lv_draw_buf_width_to_stride((uint32_t)w,
2770	        LV_COLOR_FORMAT_RGB565) * (size_t)h;
2771	    vmap_free(s_climb_cbuf);
2772	    s_climb_cbuf = vmap_malloc(bytes);
2773	    if (s_climb_cbuf == NULL) {
2774	        s_climb_cw = 0;
2775	        s_climb_ch = 0;
2776	        return false;
2777	    }
2778	    s_climb_cw = w;
2779	    s_climb_ch = h;
2780	    lv_canvas_set_buffer(s_sh.climb_canvas, s_climb_cbuf, w, h,
2781	        LV_COLOR_FORMAT_RGB565);
2782	    lv_obj_set_size(s_sh.climb_canvas, w, h);
2783	    return true;
2784	}
