2786	/**
2787	 * @brief 把剖面一段画进画布图层。
2788	 * @param layer 画布图层。
2789	 * @param i 段下标（点 i→i+1）。
2790	 * @param as_done true 则强制灰色（刚骑过的那截）。
2791	 */
2792	static void helm_climb_canvas_seg(lv_layer_t * layer, uint32_t i, bool as_done)
2793	{
2794	    lv_point_t a;
2795	    lv_point_t b;
2796	    lv_point_precise_t p1;
2797	    lv_point_precise_t p2;
2798	    lv_color_t fill;
2799	    lv_color_t ink;
2800	    uint8_t z;
2801	
2802	    if (layer == NULL || s_sh.climb_chart == NULL || s_sh.climb_ser == NULL ||
2803	        i + 1u >= s_sh.climb_n) {
2804	        return;
2805	    }
2806	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, i, &a);
2807	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, i + 1u, &b);
2808	    p1.x = a.x;
2809	    p1.y = a.y;
2810	    p2.x = b.x;
2811	    p2.y = b.y;
2812	    if (as_done || i < (uint32_t)s_sh.climb_now) {
2813	        fill = helm_color_snap(HELM_COLOR_ELEV_DONE);
2814	        ink = helm_color(HELM_COLOR_ELEV_DONE_INK);
2815	    } else {
2816	        z = s_climb_zone[i];
2817	        fill = helm_color_snap(helm_climb_zone_fill(z));
2818	        ink = helm_color(helm_climb_zone_ink(z));
2819	    }
2820	    helm_climb_paint_seg(layer, p1, p2, s_climb_ch - 1, fill, ink, 2);
2821	}
