2823	/**
2824	 * @brief 标脏画布上 [i0, i1] 对应的水平窄条。
2825	 * @param i0 起始采样点下标。
2826	 * @param i1 结束采样点下标。
2827	 * @details 关闭 `lv_canvas_finish_layer` 的整对象 invalidate 后，用本函数只刷刚改的那一截。
2828	 */
2829	static void helm_climb_canvas_inval_span(uint32_t i0, uint32_t i1)
2830	{
2831	    lv_point_t a;
2832	    lv_point_t b;
2833	    lv_area_t area;
2834	    int32_t orig;
2835	    int32_t lo;
2836	    int32_t hi;
2837	    uint32_t last;
2838	
2839	    if (s_sh.climb_canvas == NULL || s_sh.climb_n < 2u) {
2840	        return;
2841	    }
2842	    last = (uint32_t)s_sh.climb_n - 1u;
2843	    if (i0 > last) {
2844	        i0 = last;
2845	    }
2846	    if (i1 > last) {
2847	        i1 = last;
2848	    }
2849	    lv_obj_get_coords(s_sh.climb_canvas, &area);
2850	    orig = area.x1;
2851	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, i0, &a);
2852	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, i1, &b);
2853	    lo = a.x < b.x ? a.x : b.x;
2854	    hi = a.x < b.x ? b.x : a.x;
2855	    area.x1 = orig + lo - 2;
2856	    area.x2 = orig + hi + 3;
2857	    lv_obj_invalidate_area(s_sh.climb_canvas, &area);
2858	}
