2860	/**
2861	 * @brief 把 [i0, i1) 段画进已有画布（竖线前进时只涂灰，不整图重绘）。
2862	 * @param i0 起始段。
2863	 * @param i1 结束段（不含）。
2864	 * @param as_done 强制灰色。
2865	 * @details `lv_canvas_finish_layer` 前后关掉 display invalidation，再按窄条标脏，
2866	 *          避免整张画布进入切页脏区。
2867	 */
2868	static void helm_climb_canvas_paint_range(uint32_t i0, uint32_t i1, bool as_done)
2869	{
2870	    lv_layer_t layer;
2871	    lv_display_t * disp;
2872	    uint32_t i;
2873	
2874	    if (s_sh.climb_canvas == NULL || s_sh.climb_n < 2u || i0 >= i1) {
2875	        return;
2876	    }
2877	    if (i1 > (uint32_t)s_sh.climb_n - 1u) {
2878	        i1 = (uint32_t)s_sh.climb_n - 1u;
2879	    }
2880	    lv_canvas_init_layer(s_sh.climb_canvas, &layer);
2881	    for (i = i0; i < i1; i++) {
2882	        helm_climb_canvas_seg(&layer, i, as_done);
2883	    }
2884	    disp = lv_obj_get_display(s_sh.climb_canvas);
2885	    if (disp) {
2886	        lv_display_enable_invalidation(disp, false);
2887	    }
2888	    lv_canvas_finish_layer(s_sh.climb_canvas, &layer);
2889	    if (disp) {
2890	        lv_display_enable_invalidation(disp, true);
2891	    }
2892	    helm_climb_canvas_inval_span(i0, i1);
2893	}
