2895	/**
2896	 * @brief 把当前路线海拔剖面烘焙到画布（只在换路线时调用）。
2897	 * @return 成功则图表隐藏，切页只贴这一张图。
2898	 * @details 切页 220 ms crossfade 若走 DRAW_TASK，每帧会提交约 59 段三角形，
2899	 *          `lv_timer_handler` 可达 150–270 ms。烘焙后只 blit。失败返回 false。
2900	 */
2901	static bool helm_climb_canvas_bake(void)
2902	{
2903	    lv_layer_t layer;
2904	    uint32_t i;
2905	
2906	    if (!s_sh.climb_nav || s_sh.climb_n < 2u || !helm_climb_canvas_ensure()) {
2907	        return false;
2908	    }
2909	    lv_canvas_fill_bg(s_sh.climb_canvas, helm_color(HELM_COLOR_PAPER),
2910	        LV_OPA_COVER);
2911	    lv_canvas_init_layer(s_sh.climb_canvas, &layer);
2912	    for (i = 0; i + 1u < s_sh.climb_n; i++) {
2913	        helm_climb_canvas_seg(&layer, i, false);
2914	    }
2915	    lv_canvas_finish_layer(s_sh.climb_canvas, &layer);
2916	    lv_obj_add_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN);
2917	    lv_obj_remove_flag(s_sh.climb_canvas, LV_OBJ_FLAG_HIDDEN);
2918	    helm_climb_cursor_place();
2919	
2920	    /*
2921	     * 烘焙收尾（2026-09-27）：
2922	     *   ① `lv_obj_update_layout()`：重建后布局可能还没跑过（几何为 0 ⇒ invalidate 的是空区域）；
2923	     *   ② 显式 `lv_obj_invalidate()`：`lv_canvas_finish_layer()` 只标画布自身的脏区，而换主题
2924	     *      这条路上画布是刚重建的新对象 ⇒ 补一次，保证新配色真的上屏。
2925	     * 保留一行低频日志（一次烘焙一行，路线变化才触发）：换主题后再遇到"图是空的"，
2926	     * 这一行就能分清"没数据（n/ele 为 0）"还是"有数据但没上屏"。
2927	     */
2928	    lv_obj_update_layout(s_sh.climb_canvas);
2929	    lv_obj_invalidate(s_sh.climb_canvas);
2930	    lv_obj_invalidate(s_sh.climb_chart);
2931	    syslog(LOG_NOTICE, "[climb] bake nav=%d n=%d ele=%d..%d\n",
2932	           (int)s_sh.climb_nav, (int)s_sh.climb_n,
2933	           (int)(s_sh.climb_n >= 2u ? (s_climb_eles[0] < s_climb_eles[s_sh.climb_n - 1u]
2934	                                      ? s_climb_eles[0] : s_climb_eles[s_sh.climb_n - 1u]) : 0),
2935	           (int)(s_sh.climb_n >= 2u ? (s_climb_eles[0] > s_climb_eles[s_sh.climb_n - 1u]
2936	                                      ? s_climb_eles[0] : s_climb_eles[s_sh.climb_n - 1u]) : 0));
2937	
2938	    return true;
2939	}
