2941	/**
2942	 * @brief 只标脏当前位置竖线附近一条窄带（非导航「经过海拔」用）。
2943	 * @param x 点在图表内的相对 x。
2944	 */
2945	/**
2946	 * @brief 标脏当前位置指示器（小倒三角）所在的小方块。
2947	 * @param x 图表内相对 x（三角中心）。
2948	 * @param y 图表内相对 y（尖端）。
2949	 * @details 2026-09-25：指示器由"2 px 通高竖线"改成小倒三角后，标脏也从
2950	 *          "整列高度 × 7 px 宽"缩成三角的包围盒 + 1 px 余量 —— 导航烘焙模式下
2951	 *          这一条要重绘画布，小方块明显更省。
2952	 */
2953	static void helm_climb_inval_cursor_at(int32_t x, int32_t y)
2954	{
2955	    lv_area_t a;
2956	    const int32_t half = HELM_CLIMB_MARK_W / 2 + 1;
2957	
2958	    if (s_sh.climb_chart == NULL) {
2959	        return;
2960	    }
2961	    lv_obj_get_coords(s_sh.climb_chart, &a);
2962	    a.x1 += x - half;
2963	    a.x2 = a.x1 + 2 * half;
2964	    a.y1 += y - (HELM_CLIMB_MARK_H + 1);
2965	    a.y2 = a.y1 + (HELM_CLIMB_MARK_H + 2);
2966	    lv_obj_invalidate_area(s_sh.climb_chart, &a);
2967	}
