2969	/**
2970	 * @brief 标脏 [xa, xb] 整列高度，让刚骑过的那截从彩块改成灰。
2971	 * @param xa 图表内相对 x。
2972	 * @param xb 图表内相对 x。
2973	 *
2974	 * @note 导航剖面专用。竖线未动时不要调用。
2975	 */
2976	static void helm_climb_inval_span_x(int32_t xa, int32_t xb)
2977	{
2978	    lv_area_t a;
2979	    int32_t orig;
2980	    int32_t lo;
2981	    int32_t hi;
2982	
2983	    if (s_sh.climb_chart == NULL) {
2984	        return;
2985	    }
2986	    lv_obj_get_coords(s_sh.climb_chart, &a);
2987	    orig = a.x1;
2988	    lo = xa < xb ? xa : xb;
2989	    hi = xa < xb ? xb : xa;
2990	    a.x1 = orig + lo - 2;
2991	    a.x2 = orig + hi + 3;
2992	    lv_obj_invalidate_area(s_sh.climb_chart, &a);
2993	}
