2995	/**
2996	 * @brief 当前位置下标变化时只移动竖线（及导航时那一窄条灰色），不 refresh 整张图。
2997	 * @param id 新的采样点下标。
2998	 * @details 画布已显示：前进则把 [prev, id) 涂灰并挪竖线；后退则整图重烘焙。
2999	 *          未烘焙：只标脏窄条。画布可见时即使图表已隐藏也要处理。
3000	 */
3001	static void helm_climb_cursor_move(uint32_t id)
3002	{
3003	    lv_point_t p;
3004	    lv_point_t prev_p;
3005	    uint32_t n;
3006	    uint8_t prev;
3007	    bool baked;
3008	
3009	    if (s_sh.climb_ser == NULL || s_sh.climb_n < 2u) {
3010	        return;
3011	    }
3012	    baked = (s_sh.climb_canvas != NULL) &&
3013	            !lv_obj_has_flag(s_sh.climb_canvas, LV_OBJ_FLAG_HIDDEN);
3014	    if (!baked && (s_sh.climb_chart == NULL ||
3015	            lv_obj_has_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN))) {
3016	        return;
3017	    }
3018	
3019	    n = baked ? (uint32_t)s_sh.climb_n : lv_chart_get_point_count(s_sh.climb_chart);
3020	    if (n < 2u) {
3021	        return;
3022	    }
3023	    if (id >= n) {
3024	        id = n - 1u;
3025	    }
3026	    if (s_sh.climb_now == (uint8_t)id) {
3027	        return;
3028	    }
3029	
3030	    prev = s_sh.climb_now;
3031	    s_sh.climb_now = (uint8_t)id;
3032	    if (baked) {
3033	        if ((uint32_t)id > (uint32_t)prev) {
3034	            helm_climb_canvas_paint_range((uint32_t)prev, (uint32_t)id, true);
3035	            helm_climb_cursor_place();
3036	        } else {
3037	            (void)helm_climb_canvas_bake();
3038	        }
3039	        return;
3040	    }
3041	
3042	    lv_obj_update_layout(s_sh.climb_chart);
3043	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, prev, &prev_p);
3044	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, id, &p);
3045	    if (s_sh.climb_nav) {
3046	        helm_climb_inval_span_x(prev_p.x, p.x);
3047	    } else {
3048	        /* 指示器跟着剖面点 ⇒ 新旧位置各标脏一次；坐标与绘制同约定（不补 pad）。 */
3049	        helm_climb_inval_cursor_at(prev_p.x, prev_p.y - 2);
3050	        helm_climb_inval_cursor_at(p.x, p.y - 2);
3051	    }
3052	}
