3054	/**
3055	 * @brief 按剖面海拔范围加边距，得到图表 Y 轴。
3056	 * @param eles 海拔采样（米）。
3057	 * @param n 采样点数。
3058	 * @param[out] mn 轴下限。
3059	 * @param[out] mx 轴上限。
3060	 */
3061	static void helm_climb_axis(const int16_t * eles, uint32_t n,
3062	    int32_t * mn, int32_t * mx)
3063	{
3064	    uint32_t i;
3065	    int32_t lo = 32767;
3066	    int32_t hi = -32767;
3067	    int32_t pad;
3068	
3069	    for (i = 0; i < n; i++) {
3070	        if (eles[i] == (int16_t)VGRF_ELE_UNKNOWN) {
3071	            continue;
3072	        }
3073	        if ((int32_t)eles[i] < lo) {
3074	            lo = eles[i];
3075	        }
3076	        if ((int32_t)eles[i] > hi) {
3077	            hi = eles[i];
3078	        }
3079	    }
3080	    if (lo > hi) {
3081	        lo = 0;
3082	        hi = 100;
3083	    }
3084	    pad = (hi - lo) / 10;
3085	    if (pad < 8) {
3086	        pad = 8;
3087	    }
3088	    *mn = lo - pad;
3089	    *mx = hi + pad;
3090	}
