3092	/**
3093	 * @brief 路线或近 30 分钟记录变化时重载海拔剖面。
3094	 * @details 导航：按总里程均匀取样，并一次性写入 `s_climb_zone`（骑行中不重算坡度）。
3095	 *          烘焙成功则隐藏图表、不再 `lv_chart_refresh`。
3096	 *          未导航或烘焙失败：显示图表并 refresh 一次（「经过海拔」仍用青绿渐变）。
3097	 */
3098	static void helm_climb_profile_reload(void)
3099	{
3100	    int16_t eles[HELM_CLIMB_PROF_N];
3101	    uint32_t n = 0;
3102	    uint32_t now_idx = LV_CHART_POINT_NONE;
3103	    uint32_t i;
3104	    int32_t mn;
3105	    int32_t mx;
3106	    bool nav;
3107	    int16_t last = 0;
3108	    bool have = false;
3109	    uint32_t fp_pts = 0;
3110	    uint32_t fp_total_cm = 0;
3111	
3112	    if (s_sh.climb_chart == NULL || s_sh.climb_ser == NULL) {
3113	        return;
3114	    }
3115	
3116	    nav = helm_nav_on();
3117	#if VMAP_ROUTE_ENABLE
3118	    if (nav) {
3119	        uint32_t cur = 0;
3120	
