3491	static void helm_autopause_tick(void)
3492	{
3493	    uint32_t now;
3494	    const bicycle_runtime_t * rt;
3495	    bool recording;
3496	    bool moving;
3497	
3498	    if (!helm_riding()) {
3499	        helm_ride_dwell_reset();
3500	        return;
3501	    }
3502	
3503	    /* 保存框仍在主界面上，不在背后偷偷恢复。菜单盖住时继续判运动。 */
3504	    if (helm_save_open()) {
3505	        return;
3506	    }
3507	
3508	    if (s_sh.paused && !s_sh.pause_auto) {
3509	        helm_ride_dwell_reset();
3510	        return;
3511	    }
3512	
3513	    if (!myvendor_devctl_autopause_get()) {
3514	        helm_ride_dwell_reset();
3515	        return;
3516	    }
3517	
3518	    now = lv_tick_get();
3519	    rt = bicycle_runtime_get();
3520	    recording = rt && rt->recording;
3521	    moving = s_sh.paused ? bicycle_runtime_is_moving(true)
3522	                         : bicycle_runtime_is_moving(false);
3523	
3524	    if (moving) {
3525	        s_still_since = 0;
3526	        if (s_move_since == 0) {
3527	            s_move_since = now;
3528	        }
3529	
3530	        if (s_sh.paused && s_sh.pause_auto &&
3531	            lv_tick_elaps(s_move_since) >= HELM_AUTORESUME_MS) {
3532	            map_page_resume_ride(s_sh.map);
3533	            s_sh.pause_auto = false;
3534	            helm_shell_set_paused(false);
3535	            s_autopause_hold_since = now;
3536	            if (s_autopause_hold_since == 0u) {
3537	                s_autopause_hold_since = 1u;
3538	            }
3539	            helm_ride_dwell_reset();
3540	        }
3541	    } else {
3542	        s_move_since = 0;
3543	        if (helm_autopause_held()) {
3544	            s_still_since = 0;
3545	        } else if (s_still_since == 0) {
3546	            s_still_since = now;
3547	        }
3548	
3549	        /* 模拟轨迹回放期间**不要自动暂停**：回放的 GPS 数据不是真实运动
3550	         * （速度/是否移动由 runtime 的判定决定），一暂停就把"导航测试"打断，
3551	         * 屏幕上弹"自动暂停"。测试链路要的是纯导航，所以这里直接屏蔽。 */
3552	        if (recording && !bicycle_gpx_sim_active() && !s_sh.paused &&
3553	            s_still_since != 0 &&
3554	            lv_tick_elaps(s_still_since) >= HELM_AUTOPAUSE_MS) {
3555	            map_page_pause_ride(s_sh.map);
3556	            s_sh.pause_auto = true;
3557	            helm_shell_set_paused(true);
3558	            helm_ride_dwell_reset();
3559	        }
3560	    }
3561	}
