6981	/**
6982	 * @brief 图表折线绘制前回调：导航烘焙失败时的现场绘制回退路径。
6983	 * @param e LV_EVENT_DRAW_TASK_ADDED。
6984	 *
6985	 * @details 画布可见时把折线透明并立即返回，切页只 blit 烘焙图。
6986	 *          回退路径隐藏 LVGL 单色折线，只提交与脏区相交的段。
6987	 *          非导航「经过海拔」仍用青绿渐变面积。
6988	 */
6989	static void helm_climb_draw_task(lv_event_t * e)
6990	{
6991	    lv_obj_t * obj = lv_event_get_target_obj(e);
6992	    lv_draw_task_t * draw_task = lv_event_get_draw_task(e);
6993	    lv_draw_dsc_base_t * base_dsc;
6994	    lv_draw_line_dsc_t * draw_line_dsc;
6995	    lv_color_t fill;
6996	    lv_area_t coords;
6997	    int32_t i;
6998	
6999	    if (obj == NULL || draw_task == NULL) {
7000	        return;
7001	    }
7002	
7003	    base_dsc = (lv_draw_dsc_base_t *)lv_draw_task_get_draw_dsc(draw_task);
7004	    if (base_dsc == NULL || base_dsc->layer == NULL ||
7005	        base_dsc->part != LV_PART_ITEMS ||
7006	        lv_draw_task_get_type(draw_task) != LV_DRAW_TASK_TYPE_LINE) {
7007	        return;
7008	    }
7009	
7010	    draw_line_dsc = lv_draw_task_get_line_dsc(draw_task);
7011	    if (draw_line_dsc == NULL || draw_line_dsc->points == NULL ||
7012	        draw_line_dsc->point_cnt < 2) {
7013	        return;
7014	    }
7015	
7016	    lv_obj_get_coords(obj, &coords);
7017	
7018	    if (s_sh.climb_canvas && !lv_obj_has_flag(s_sh.climb_canvas, LV_OBJ_FLAG_HIDDEN)) {
7019	        draw_line_dsc->opa = LV_OPA_TRANSP;
7020	        return;
7021	    }
7022	
7023	    if (s_sh.climb_nav && s_sh.climb_n >= 2u) {
7024	        int32_t lw = draw_line_dsc->width;
7025	        uint32_t now = s_sh.climb_now;
7026	        const lv_area_t * clip = &base_dsc->layer->_clip_area;
7027	
7028	        draw_line_dsc->opa = LV_OPA_TRANSP;
7029	        for (i = 0; i < draw_line_dsc->point_cnt - 1; i++) {
7030	            lv_point_precise_t p1 = draw_line_dsc->points[i];
7031	            lv_point_precise_t p2 = draw_line_dsc->points[i + 1];
7032	            uint8_t z;
7033	            uint32_t fh;
7034	            uint32_t sh;
7035	
7036	            if (p1.x == LV_DRAW_LINE_POINT_NONE || p1.y == LV_DRAW_LINE_POINT_NONE ||
7037	                p2.x == LV_DRAW_LINE_POINT_NONE || p2.y == LV_DRAW_LINE_POINT_NONE) {
7038	                continue;
7039	            }
7040	            if (!helm_climb_seg_in_clip(clip, p1, p2, coords.y2, lw)) {
7041	                continue;
7042	            }
7043	            z = ((uint32_t)i + 1u < s_sh.climb_n) ? s_climb_zone[i] : 0u;
7044	            if ((uint32_t)i < now) {
7045	                fh = HELM_COLOR_ELEV_DONE;
7046	                sh = HELM_COLOR_ELEV_DONE_INK;
7047	            } else {
7048	                fh = helm_climb_zone_fill(z);
7049	                sh = helm_climb_zone_ink(z);
7050	            }
7051	            helm_climb_paint_seg(base_dsc->layer, p1, p2, coords.y2,
7052	                helm_color_snap(fh), helm_color(sh), lw);
7053	        }
7054	        return;
7055	    }
7056	
7057	    /* 逐行填（2026-09-25 第二版，与主页 spark 同法）：每行一个**纯色**矩形，alpha 由
7058	     * 一条**全局**竖直斜坡给出 —— 越靠图表上方越实、到图底淡成 0，于是山峰处厚实、
7059	     * 谷地处轻薄；比原来"每段一个三角形 + 一块 20% 淡洗"干净得多。
7060	     *
7061	     * 换掉老写法的两个理由：
7062	     *   · 老写法的矩形 x 区间是 [min, max] **两端都含** ⇒ 相邻段在数据点那一列重叠
7063	     *     1 px、混合两次 ⇒ 偏深竖线；三角形的 bbox 又各按自己取整 ⇒ 等 alpha 线是
7064	     *     按段错开的锯齿（观感"脏"）。
7065	     *   · 本板 EPIC 加速单元**没有 TRIANGLE**（只有 FILL/IMAGE/BORDER/LABEL/LAYER），
7066	     *     三角形要回退 SW 逐行生成遮罩；纯色矩形全部走 EPIC 的 FILL。
7067	     *
7068	     * 行、列都只扫**裁剪区内** —— 光标移动时只标脏一个小方块，不能整片重画。 */
7069	    fill = helm_color_snap(HELM_COLOR_CLIMB_FILL);
7070	    {
7071	        const lv_area_t * clip = &base_dsc->layer->_clip_area;
7072	        const int32_t n_pts = (int32_t)draw_line_dsc->point_cnt;
7073	        const int32_t fh = coords.y2 - coords.y1 + 1;
7074	        int32_t x_first = (int32_t)draw_line_dsc->points[0].x;
7075	        int32_t x_last = (int32_t)draw_line_dsc->points[n_pts - 1].x;
7076	        int32_t y_from = coords.y1 > clip->y1 ? coords.y1 : clip->y1;
7077	        int32_t y_to = coords.y2 < clip->y2 ? coords.y2 : clip->y2;
7078	        int32_t x_from = x_first > clip->x1 ? x_first : clip->x1;
7079	        int32_t x_to = x_last < clip->x2 ? x_last : clip->x2;
7080	        int32_t y;
7081	
7082	        if (fh > 0 && x_to >= x_from) {
7083	            for (y = y_from; y <= y_to; y++) {
7084	                lv_draw_rect_dsc_t rect_dsc;
7085	                lv_area_t rect_area;
7086	                lv_opa_t opa = (lv_opa_t)(HELM_CLIMB_FILL_TOP_OPA -
7087	                    (uint32_t)(y - coords.y1) * HELM_CLIMB_FILL_TOP_OPA / (uint32_t)fh);
7088	                uint32_t seg = 0;
7089	                int32_t run = 0;
7090	                bool in = false;
7091	                int32_t x;
7092	
7093	                if ((int32_t)opa < 6) {
7094	                    continue;       /* 淡到看不见了：这一行不画 */
7095	                }
7096	
7097	                lv_draw_rect_dsc_init(&rect_dsc);
7098	                rect_dsc.bg_color = fill;
7099	                rect_dsc.bg_opa = opa;
7100	                rect_area.y1 = y;
7101	                rect_area.y2 = y;
7102	
7103	                for (x = x_from; x <= x_to; x++) {
7104	                    bool under = false;
7105	
7106	                    while (seg < (uint32_t)n_pts - 2u &&
7107	                           (int32_t)draw_line_dsc->points[seg + 1].x < x) {
7108	                        seg++;
7109	                    }
7110	
7111	                    {
7112	                        lv_point_precise_t a = draw_line_dsc->points[seg];
7113	                        lv_point_precise_t b = draw_line_dsc->points[seg + 1];
7114	
7115	                        /* 端点无效或该段不向右延伸：这一列当作"曲线不在上方"，不填。 */
7116	                        if (a.x != LV_DRAW_LINE_POINT_NONE &&
7117	                            a.y != LV_DRAW_LINE_POINT_NONE &&
7118	                            b.x != LV_DRAW_LINE_POINT_NONE &&
7119	                            b.y != LV_DRAW_LINE_POINT_NONE &&
7120	                            b.x > a.x) {
7121	                            int32_t yc = (int32_t)a.y +
7122	                                         (int32_t)((b.y - a.y) * (x - a.x) / (b.x - a.x));
7123	
7124	                            under = (yc < y);
7125	                        }
7126	                    }
7127	
7128	                    if (under && !in) {
7129	                        run = x;
7130	                        in = true;
7131	                    } else if (!under && in) {
7132	                        rect_area.x1 = run;
7133	                        rect_area.x2 = x - 1;
7134	                        if (rect_area.x2 >= rect_area.x1) {
7135	                            lv_draw_rect(base_dsc->layer, &rect_dsc, &rect_area);
7136	                        }
7137	                        in = false;
7138	                    }
7139	                }
7140	
7141	                if (in) {
7142	                    rect_area.x1 = run;
7143	                    rect_area.x2 = x_to;
7144	                    if (rect_area.x2 >= rect_area.x1) {
7145	                        lv_draw_rect(base_dsc->layer, &rect_dsc, &rect_area);
7146	                    }
7147	                }
7148	            }
7149	        }
7150	    }
7151	}
