7196	/**
7197	 * @brief 把"当前位置"指示（点阵倒三角）画到图层上。
7198	 * @param layer 目标层。
7199	 * @param cx    三角形水平中心（图层坐标）。
7200	 * @param tip_y 尖端 y（图层坐标）；三角形占据它上方 HELM_CLIMB_MARK_H−1 行。
7201	 *
7202	 * @details 现场模式（图表在画、未烘焙）走这里；烘焙模式（导航）由 `climb_cursor`
7203	 *          这个 `lv_image` 对象自己画 ⇒ 两条路径共用同一份点阵，外观一致。
7204	 */
7205	static void helm_climb_mark_blit(lv_layer_t * layer, int32_t cx, int32_t tip_y)
7206	{
7207	    lv_draw_image_dsc_t d;
7208	    lv_area_t a;
7209	
7210	    lv_draw_image_dsc_init(&d);
7211	    d.src = &s_climb_mark_dsc;
7212	    a.x1 = cx - HELM_CLIMB_MARK_W / 2;
7213	    a.x2 = a.x1 + (HELM_CLIMB_MARK_W - 1);
7214	    a.y2 = tip_y;
7215	    a.y1 = a.y2 - (HELM_CLIMB_MARK_H - 1);
7216	    lv_draw_image(layer, &d, &a);
7217	}
