7219	/**
7220	 * @brief 绘制当前位置指示（小倒三角）。导航用黑色，经过海拔用青绿。
7221	 * @param e LV_EVENT_DRAW_POST。
7222	 * @details 画布可见时指示由 `climb_cursor` 对象承担，本回调直接返回。
7223	 */
7224	static void helm_climb_draw(lv_event_t * e)
7225	{
7226	    lv_layer_t * layer = lv_event_get_layer(e);
7227	    lv_area_t coords;
7228	    lv_point_t p;
7229	    uint32_t id;
7230	    uint32_t n;
7231	
7232	    if (layer == NULL || s_sh.climb_chart == NULL || s_sh.climb_ser == NULL) {
7233	        return;
7234	    }
7235	    if (s_sh.climb_canvas && !lv_obj_has_flag(s_sh.climb_canvas, LV_OBJ_FLAG_HIDDEN)) {
7236	        return;
7237	    }
7238	    if (lv_obj_has_flag(s_sh.climb_chart, LV_OBJ_FLAG_HIDDEN)) {
7239	        return;
7240	    }
7241	
7242	    n = lv_chart_get_point_count(s_sh.climb_chart);
7243	    if (n < 2u || s_sh.climb_n < 2u) {
7244	        return;
7245	    }
7246	
7247	    id = s_sh.climb_nav ? (uint32_t)s_sh.climb_now : (n - 1u);
7248	    if (id >= n) {
7249	        id = n - 1u;
7250	    }
7251	    lv_chart_get_point_pos_by_id(s_sh.climb_chart, s_sh.climb_ser, id, &p);
7252	    lv_obj_get_coords(s_sh.climb_chart, &coords);
7253	    /* 尖端贴在剖面点**上方 2 px**，三角整体在折线之上；坐标约定与剖面绘制一致
7254	     * （**不补图表自己的 pad** —— 见 `helm_climb_cursor_place()` 的长注释）。 */
7255	    {
7256	        const int32_t half = HELM_CLIMB_MARK_W / 2;
7257	        int32_t cx = coords.x1 + p.x;
7258	        int32_t tip = coords.y1 + p.y - 2;
7259	
7260	        if (cx < coords.x1 + half) {
7261	            cx = coords.x1 + half;
7262	        } else if (cx > coords.x2 - half) {
7263	            cx = coords.x2 - half;
7264	        }
7265	        if (tip < coords.y1 + (HELM_CLIMB_MARK_H - 1)) {
7266	            tip = coords.y1 + (HELM_CLIMB_MARK_H - 1);
7267	        } else if (tip > coords.y2) {
7268	            tip = coords.y2;
7269	        }
7270	        helm_climb_mark_blit(layer, cx, tip);
7271	    }
7272	}
