7280	static void helm_build_climb(lv_obj_t * root)
7281	{
7282	    lv_obj_t * card;
7283	    lv_obj_t * chart;
7284	
7285	    /* 用户 2026-09-26 给的图：**剖面卡在上、六格在下**，整页满高。
7286	     * ⇒ 海拔页不再给底部三格数据条让位（`rot_on` 里去掉了 CLIMB），
7287	     *   否则 80px 会把剖面卡从 108 压到 56。 */
7288	    s_sh.climb = helm_overlay(root, HELM_SUBBAR_H,
7289	                              HELM_PAGE_H - HELM_SUBBAR_H);
7290	    helm_speed_head(s_sh.climb, "海拔", NULL, NULL);
7291	
7292	    /* 剖面卡（内层 chart/canvas/cursor 机制完全不动，只把"剩余爬升"从页头挪
7293	     * 到卡内右上角——图里它在那儿）。 */
7294	    card = lv_obj_create(s_sh.climb);
7295	    lv_obj_remove_style_all(card);
7296	    lv_obj_set_size(card, lv_pct(100), HELM_CLIMB_CARD_H);
7297	    helm_style_card(card);
7298	    lv_obj_add_flag(card, LV_OBJ_FLAG_OVERFLOW_VISIBLE);
7299	
7300	    chart = lv_chart_create(card);
7301	    lv_obj_remove_flag(chart, LV_OBJ_FLAG_CLICKABLE);
7302	    lv_obj_clear_flag(chart, LV_OBJ_FLAG_SCROLLABLE);
7303	    lv_obj_set_size(chart, lv_pct(100), lv_pct(100));
7304	    lv_obj_align(chart, LV_ALIGN_TOP_LEFT, 0, 0);
7305	    lv_obj_set_style_bg_opa(chart, LV_OPA_TRANSP, 0);
7306	    lv_obj_set_style_border_width(chart, 0, 0);
7307	    lv_obj_set_style_pad_top(chart, 22, 0);
7308	    lv_obj_set_style_pad_bottom(chart, 8, 0);
7309	    lv_obj_set_style_pad_hor(chart, 8, 0);
7310	    lv_obj_set_style_radius(chart, 0, 0);
7311	    lv_obj_set_style_line_width(chart, 2, LV_PART_ITEMS);
7312	    lv_obj_set_style_width(chart, 0, LV_PART_INDICATOR);
7313	    lv_obj_set_style_height(chart, 0, LV_PART_INDICATOR);
7314	    lv_chart_set_type(chart, LV_CHART_TYPE_LINE);
7315	    /* CIRCULAR：写点不得整图 invalidate（SHIFT 会）。导航烘焙成功后图表隐藏。 */
7316	    lv_chart_set_update_mode(chart, LV_CHART_UPDATE_MODE_CIRCULAR);
7317	    lv_chart_set_point_count(chart, HELM_CLIMB_PROF_N);
7318	    lv_chart_set_div_line_count(chart, 0, 0);
7319	    lv_obj_add_flag(chart, LV_OBJ_FLAG_SEND_DRAW_TASK_EVENTS);
7320	    lv_obj_add_event_cb(chart, helm_climb_draw_task, LV_EVENT_DRAW_TASK_ADDED, NULL);
7321	    lv_obj_add_event_cb(chart, helm_climb_draw, LV_EVENT_DRAW_POST, NULL);
7322	
7323	    s_sh.climb_chart = chart;
7324	    s_sh.climb_ser = lv_chart_add_series(chart, helm_color_snap(HELM_COLOR_CLIMB),
7325	                                         LV_CHART_AXIS_PRIMARY_Y);
7326	    lv_chart_set_all_values(chart, s_sh.climb_ser, LV_CHART_POINT_NONE);
7327	    lv_obj_add_flag(chart, LV_OBJ_FLAG_HIDDEN);
7328	
7329	    s_sh.climb_canvas = lv_canvas_create(card);
7330	    lv_obj_remove_style_all(s_sh.climb_canvas);
7331	    lv_obj_remove_flag(s_sh.climb_canvas, LV_OBJ_FLAG_CLICKABLE);
7332	    lv_obj_clear_flag(s_sh.climb_canvas, LV_OBJ_FLAG_SCROLLABLE);
7333	    lv_obj_set_size(s_sh.climb_canvas, lv_pct(100), lv_pct(100));
7334	    lv_obj_align(s_sh.climb_canvas, LV_ALIGN_TOP_LEFT, 0, 0);
7335	    lv_obj_add_flag(s_sh.climb_canvas, LV_OBJ_FLAG_HIDDEN);
7336	
7337	    /* 位置指示就是一张 `lv_image`（点阵倒三角，颜色已烧进 RGB565A8 数据）：
7338	     * 不需要自绘回调，尺寸由图片自己给，走的也是 EPIC 的 IMAGE 路径。 */
