7359	        lv_obj_t * grid;

7359	        lv_obj_t * grid;
7360	        int i2;
7361	
7362	        grid = lv_obj_create(s_sh.climb);
7363	        lv_obj_remove_style_all(grid);
7364	        helm_style_card(grid);
