7386	                lv_obj_set_style_border_width(r2, 1, 0);
7387	                lv_obj_set_style_border_color(r2,
7388	                                              helm_color(HELM_COLOR_HAIR), 0);
7389	            }
7390	
7391	            helm_cell_make(r2, s_sh.climb_rail, s_sh.climb_lab,
7392	                           s_sh.climb_val, i2 * 2);
7393	            helm_cell_make(r2, s_sh.climb_rail, s_sh.climb_lab,
7394	                           s_sh.climb_val, i2 * 2 + 1);
7395	            helm_label_set(s_sh.climb_lab[i2 * 2], kname[i2 * 2]);
7396	            helm_label_set(s_sh.climb_lab[i2 * 2 + 1], kname[i2 * 2 + 1]);
7397	        }
7398	    }
7399	
7400	    s_sh.climb_n = 0;
7401	    s_sh.climb_now = 0;
7402	    s_sh.climb_nav = false;
7403	}
