1487	/* 前方 2 km 海拔剖面。采样点数、段数、跳色阈值、三角填充 + 2px 脊线都
1488	 * 沿用旧 UI（helm_shell.c 的 HELM_CLIMB_PROF_N / helm_climb_grade_zone /
1489	 * helm_climb_paint_seg）。数据是**假数据**：按分段目标坡度累加，不是 GPX。 */
1490	static double s_elev[ELEV_PROF_N];
1491	static uint8_t s_elev_zone[ELEV_PROF_N - 1];
1492	static uint8_t s_elev_cbuf[ELEV_CANVAS_W * ELEV_CANVAS_H * 2]
1493	    __attribute__((aligned(4)));
