1495	/** 生成 2 km 假剖面：9 段不同坡度，保证灰/模式浅色/红三档都出现。 */
1496	static void elev_profile_gen(void)
1497	{
1498	    /* n = 段数，pct = 该段坡度百分数；合计 59 段。 */
1499	    static const struct {
1500	        uint8_t n;
1501	        double pct;
1502	    } plan[] = {
1503	        { 6, 0.5 },  /* 平路起步 */
1504	        { 6, 2.6 },  /* 缓上（仍算平路） */
1505	        { 6, 5.5 },  /* 中坡 */
1506	        { 6, 9.0 },  /* 陡坡 */
1507	        { 7, -3.5 }, /* 下坡 */
1508	        { 7, 4.5 },  /* 中坡 */
1509	        { 6, 7.5 },  /* 中陡 */
1510	        { 6, 0.8 },  /* 高处平路台地 */
1511	        { 6, 10.0 }, /* 最后一段陡坡 */
1512	        { 3, -4.5 }, /* 下坡收尾 */
1513	    };
1514	    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
1515	    double e = 326.0; /* 与骑行页当前海拔（R.elevation）对齐 */
1516	    int k = 0;
1517	
1518	    s_elev[0] = e;
1519	    for (size_t p = 0; p < sizeof(plan) / sizeof(plan[0]); p++) {
1520	        for (int i = 0; i < plan[p].n && k + 1 < ELEV_PROF_N; i++) {
1521	            e += step * plan[p].pct / 100.0;
1522	            s_elev[k + 1] = e;
1523	            k++;
1524	        }
1525	    }
1526	    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
1527	        const double g = fabs(s_elev[i + 1] - s_elev[i]) / step * 100.0;
1528	
1529	        s_elev_zone[i] = (g < ELEV_GRADE_FLAT) ? 0u
1530	                       : (g < ELEV_GRADE_STEEP) ? 1u
1531	                                                : 2u;
1532	    }
1533	}
