1535	/** 坡度档的填充色：0 中性灰 / 1 模式浅色 / 2 淡红。 */
1536	static uint32_t elev_fill(uint8_t z)
1537	{
1538	    if (z == 1u) {
1539	        return C_LIGHT[M_RIDE];
1540	    }
1541	    if (z == 2u) {
1542	        return 0xE8CCC4u;
1543	    }
1544	    return C_LIGHT[3]; /* 中性灰（与“平路”语义一致） */
1545	}
1546	
1547	/** 坡度档的脊线色：0 灰 / 1 模式深色 / 2 红。 */
1548	static uint32_t elev_ink(uint8_t z)
1549	{
1550	    if (z == 1u) {
1551	        return C_DEEP[M_RIDE];
1552	    }
1553	    if (z == 2u) {
1554	        return P_RED;
1555	    }
1556	    return P_TICK;
1557	}
