1559	/** 把 60 点剖面烘焙到 RGB565 画布（照旧 UI 的 canvas bake）。
1560	 * @param grid true 时画 3 条横向参考线（整页大图用）。 */
1561	static void elev_canvas_paint(lv_obj_t *cv, int w, int h, bool grid)
1562	{
1563	    lv_layer_t layer;
1564	    double mn = s_elev[0];
1565	    double mx = s_elev[0];
1566	    const int base = h - 1;
1567	    const int top = grid ? 10 : 3;
1568	    const int bot = base - top;
1569	
1570	    for (int i = 1; i < ELEV_PROF_N; i++) {
1571	        if (s_elev[i] < mn) mn = s_elev[i];
1572	        if (s_elev[i] > mx) mx = s_elev[i];
1573	    }
1574	    if (mx - mn < 1.0) {
1575	        mx = mn + 1.0;
1576	    }
1577	
1578	    lv_canvas_fill_bg(cv, lv_color_hex(P_PAPER), LV_OPA_COVER);
1579	    lv_canvas_init_layer(cv, &layer);
1580	    if (grid) {
1581	        lv_draw_line_dsc_t gd;
1582	
1583	        lv_draw_line_dsc_init(&gd);
1584	        gd.color = lv_color_hex(P_CARD);
1585	        gd.width = 1;
1586	        gd.opa = LV_OPA_COVER;
1587	        for (int k = 1; k <= 3; k++) {
1588	            gd.p1.x = 0;
1589	            gd.p1.y = top + (bot - top) * k / 4;
1590	            gd.p2.x = w - 1;
1591	            gd.p2.y = gd.p1.y;
1592	            lv_draw_line(&layer, &gd);
1593	        }
1594	    }
1595	    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
1596	        const int x1 = (i * (w - 1)) / (ELEV_PROF_N - 1);
1597	        const int x2 = ((i + 1) * (w - 1)) / (ELEV_PROF_N - 1);
1598	        const int y1 = bot - (int)lround((s_elev[i] - mn) / (mx - mn) *
1599	                                        (double)(bot - top));
1600	        const int y2 = bot - (int)lround((s_elev[i + 1] - mn) / (mx - mn) *
1601	                                         (double)(bot - top));
1602	        const uint32_t fill = elev_fill(s_elev_zone[i]);
1603	        const uint32_t ink = elev_ink(s_elev_zone[i]);
1604	        lv_draw_triangle_dsc_t tri;
1605	        lv_draw_line_dsc_t ld;
1606	
1607	        lv_draw_triangle_dsc_init(&tri);
1608	        tri.color = lv_color_hex(fill);
1609	        tri.opa = LV_OPA_COVER;
1610	        tri.grad.dir = LV_GRAD_DIR_NONE;
1611	        tri.p[0].x = x1;
1612	        tri.p[0].y = y1;
1613	        tri.p[1].x = x2;
1614	        tri.p[1].y = y2;
1615	        tri.p[2].x = x2;
1616	        tri.p[2].y = base;
1617	        lv_draw_triangle(&layer, &tri);
1618	        tri.p[0].x = x2;
1619	        tri.p[0].y = base;
1620	        tri.p[1].x = x1;
1621	        tri.p[1].y = base;
1622	        tri.p[2].x = x1;
1623	        tri.p[2].y = y1;
1624	        lv_draw_triangle(&layer, &tri);
1625	
1626	        lv_draw_line_dsc_init(&ld);
1627	        ld.color = lv_color_hex(ink);
1628	        ld.width = 2;
1629	        ld.opa = LV_OPA_COVER;
1630	        ld.round_start = 1;
1631	        ld.round_end = 1;
1632	        ld.p1.x = x1;
1633	        ld.p1.y = y1;
1634	        ld.p2.x = x2;
1635	        ld.p2.y = y2;
1636	        lv_draw_line(&layer, &ld);
1637	    }
