    case HELM_HIST_LOSS:
        return HELM_COLOR_CLIMB;
    case HELM_HIST_SPEED:
        return helm_live_speed_ink();
    case HELM_HIST_TIME:
    case HELM_HIST_DIST:
        return HELM_COLOR_NAV;
    default:
        return HELM_COLOR_INK;
    }
}

