        out->alive = true;
        if (out->fix_quality < 1) {
            out->fix_quality = 2;
        }

        if (out->hdop_x10 == 0) {
            out->hdop_x10 = 10;
        }

        return true;
    }

    have_onboard = myvendor_sys_onboard_gnss_get(&onboard);
    have_phone = myvendor_sys_phone_gnss_get(&phone);

    if (have_onboard && onboard.valid) {
        rt_sys_gnss_to_fix(&onboard, out);
        if (rt_trust_rmc()) {
            if (g_filt.have) {
                rt_filt_reset();
            }
        } else {
            rt_smooth_fix(out);
        }
        return true;
    }

    if (have_phone && phone.valid) {
        rt_sys_gnss_to_fix(&phone, out);
        if (rt_trust_rmc()) {
            if (g_filt.have) {
                rt_filt_reset();
            }
        } else {
            rt_smooth_fix(out);
        }
        return true;
    }

    if (have_onboard) {
        rt_sys_gnss_to_fix(&onboard, out);
        if (!rt_trust_rmc()) {
            rt_smooth_on_invalid();
            out->speed_kph = g_filt.speed;
        }
        return true;
    }

    if (have_phone) {
        rt_sys_gnss_to_fix(&phone, out);
        if (!rt_trust_rmc()) {
            rt_smooth_on_invalid();
            out->speed_kph = g_filt.speed;
        }
        return true;
    }

    memset(out, 0, sizeof(*out));
    rt_smooth_on_invalid();
    out->speed_kph = g_filt.speed;
    return false;
}

