static void map_page_reverse_pts(vmap_route_pt_t * pts, uint32_t n)
{
    uint32_t i;
    vmap_route_pt_t tmp;

    if (pts == NULL || n < 2u) {
        return;
    }

    for (i = 0; i < n / 2u; i++) {
        tmp = pts[i];
        pts[i] = pts[n - 1u - i];
        pts[n - 1u - i] = tmp;
    }
}

