static void helm_label_set(lv_obj_t * lab, const char * s)
{
    const char * cur;

    if (lab == NULL || s == NULL) {
        return;
    }
    cur = lv_label_get_text(lab);
    if (cur != NULL && strcmp(cur, s) == 0) {
        return;
    }
    lv_label_set_text(lab, s);
}

/**
