    /* 横轴：0 / 半程 / 全程。 */
    helm_climb_fmt_dist(buf, sizeof(buf), dist_m / 2u);
    helm_label_set(s_sh.climb_xlab[1], buf);
    helm_climb_fmt_dist(buf, sizeof(buf), dist_m);
    helm_label_set(s_sh.climb_xlab[2], buf);

    /* 当前坡度：一位小数（%）。 */
    if (rt != NULL) {
        const int g10 = (int)(rt->grade_pct * 10.0f +
                              (rt->grade_pct >= 0.0f ? 0.5f : -0.5f));

        if (g10 < 0) {
            lv_snprintf(buf, sizeof(buf), "-%d.%d", -g10 / 10, -g10 % 10);
        } else {
            lv_snprintf(buf, sizeof(buf), "%d.%d", g10 / 10, g10 % 10);
        }
        helm_climb_stat_set(0, buf);
    } else {
        helm_climb_stat_set(0, "--");
    }

    /* 累计爬升（米，四舍五入到整数）。 */
    if (rt != NULL) {
        lv_snprintf(buf, sizeof(buf), "%d", (int)(rt->gain_m + 0.5f));
        helm_climb_stat_set(1, buf);
    } else {
        helm_climb_stat_set(1, "--");
    }

    /* 最高点（当前窗口最大值）。 */
    if (have) {
        lv_snprintf(buf, sizeof(buf), "%d", (int)s_win_max);
        helm_climb_stat_set(2, buf);
    } else {
        helm_climb_stat_set(2, "--");
    }

    /* 尾行：最高点在前方 X km（没有逐点距离就整行隐藏）。 */
    if (have && helm_climb_win_step_cm() >= 1u) {
        uint64_t cm = (uint64_t)s_win_peak * (uint64_t)helm_climb_win_step_cm();
        uint32_t m = (uint32_t)(cm / 100u);

        lv_snprintf(buf, sizeof(buf), "最高点在前方 %u.%u km",
                    (unsigned)(m / 1000u), (unsigned)((m % 1000u) / 100u));
        helm_label_set(s_sh.climb_peak, buf);
        lv_obj_remove_flag(s_sh.climb_peak, LV_OBJ_FLAG_HIDDEN);
    } else if (s_sh.climb_peak != NULL) {
        lv_obj_add_flag(s_sh.climb_peak, LV_OBJ_FLAG_HIDDEN);
    }
}

/**
 * @brief 路线或近 30 分钟记录变化时重载海拔剖面。
 * @details 数据链与老页完全一致：导航走 `map_page_nav_profile_ele()`（按总里程
 *          均匀 60 点 + 当前位置），未导航走 `s_rec_ele[]`（30 分钟记录）。
 *          导航分段按真实步长算 `s_climb_zone`，骑行中不重算；换路线 / 换
 *          窗口时才重画 190×150 画布。
 */
static void helm_climb_profile_reload(void)
{
    int16_t eles[HELM_CLIMB_PROF_N];
    uint32_t n = 0;
    uint32_t now_idx = LV_CHART_POINT_NONE;
    uint32_t i;
    bool nav;
    int16_t last = 0;
    bool have = false;
    uint32_t fp_pts = 0;
    uint32_t fp_total_cm = 0;

    if (s_sh.climb == NULL) {
        return;
    }

    nav = helm_nav_on();
#if VMAP_ROUTE_ENABLE
    if (nav) {
        uint32_t cur = 0;

        n = map_page_nav_profile_ele(s_sh.map, eles, HELM_CLIMB_PROF_N, &cur);
        (void)map_page_nav_progress(s_sh.map, &fp_pts, &fp_total_cm, NULL, n);
        if (n >= 2u) {
            now_idx = cur;
        }
    } else
#endif
    if (helm_riding() && s_rec_ele_n >= 2u) {
        n = s_rec_ele_n;
        memcpy(eles, s_rec_ele, (size_t)n * sizeof(eles[0]));
        fp_pts = n;
        fp_total_cm = 0;
    }

    s_climb_fp_pts = fp_pts;
    s_climb_fp_total_cm = fp_total_cm;
    s_climb_fp_rec_n = nav ? 0 : (uint8_t)s_rec_ele_n;
    s_climb_fp_rec_slot = nav ? 0xffffffffu : s_rec_ele_slot;
    s_sh.climb_nav = nav;

    if (n < 2u) {
        s_sh.climb_n = 0;
        s_sh.climb_now = 0;
        helm_climb_win_build(0);
        return;
    }

    for (i = 0; i < n; i++) {
        if (eles[i] != (int16_t)VGRF_ELE_UNKNOWN) {
            last = eles[i];
            have = true;
            break;
        }
    }
    if (!have) {
        s_sh.climb_n = 0;
        s_sh.climb_now = 0;
        helm_climb_win_build(0);
        return;
    }

    for (i = 0; i < n; i++) {
        int16_t e = eles[i];

        if (e == (int16_t)VGRF_ELE_UNKNOWN) {
            e = last;
        } else {
            last = e;
        }
        s_climb_eles[i] = e;
    }
    if (nav && n >= 2u) {
        uint32_t step_cm = (fp_total_cm > 0u) ? (fp_total_cm / (n - 1u)) : 0u;

        if (step_cm < 1u) {
            step_cm = 1u;
        }
        for (i = 0; i + 1u < n; i++) {
            s_climb_zone[i] = helm_climb_grade_zone(s_climb_eles[i],
                s_climb_eles[i + 1u], step_cm);
        }
    }

    s_sh.climb_n = (uint8_t)n;
    /* 导航：窗口从当前位置画到终点；本机记录：整段从最早一点画起。 */
    s_sh.climb_now = (uint8_t)((nav && now_idx < n) ? now_idx : 0u);
    helm_climb_win_build(s_sh.climb_now);

    /* 一次换路线一行（低频）：点数 / 窗口 / 步长 / 覆盖距离，取证与现场定位共用。 */
    syslog(LOG_NOTICE, "[climb] prof nav=%d n=%d win=%d step=%ldcm d=%ldm\n",
           (int)nav, (int)n, (int)s_win_n, (long)s_win_step_cm,
           (long)helm_climb_win_dist_m());
}

/**
 * @brief 海拔页周期刷新（500 ms UI 节拍，与老页同拍）。
 * @param rt 当前骑行快照，可 NULL。
 * @param page_i 当前页序号（本页不使用）。
 * @param page_n 总页数（本页不使用）。
 * @details 路线指纹未变时只做「窗口是否要前移」的判断；窗没变就只刷文案
 *          （标签同文案不重设），绝不重画画布。
 */
static void helm_climb_tick(const bicycle_runtime_t * rt, uint8_t page_i,
    uint8_t page_n)
{
    uint32_t now_idx = 0;
    bool reload = true;

    LV_UNUSED(page_i);
    LV_UNUSED(page_n);
    if (s_sh.climb == NULL) {
        return;
    }

#if VMAP_ROUTE_ENABLE
    if (helm_nav_on()) {
        uint32_t pts = 0;
        uint32_t total_cm = 0;
        uint32_t prof_n = s_sh.climb_n >= 2u ? s_sh.climb_n : HELM_CLIMB_PROF_N;

        if (map_page_nav_progress(s_sh.map, &pts, &total_cm, &now_idx, prof_n)
            && pts == s_climb_fp_pts && total_cm == s_climb_fp_total_cm
            && s_sh.climb_nav) {
            reload = false;
        }
    } else
#endif
    if (!s_sh.climb_nav && s_rec_ele_n == s_climb_fp_rec_n
        && s_rec_ele_slot == s_climb_fp_rec_slot) {
        reload = false;
        now_idx = 0;
    }

    if (s_climb_rebake) {
        s_climb_rebake = false;
        /* 换主题后颜色变了：用既有窗口重画一次，不去重新取数。 */
        helm_climb_canvas_repaint();
    }

    if (reload) {
        helm_climb_profile_reload();
    } else {
        helm_climb_win_apply(now_idx);
    }
    helm_climb_labels_refresh(rt);
}
"}

