/**
 * @brief 海拔页绝对坐标标签（页面根是 flex 容器，浮起的子对象才按 set_pos 摆）。
 */
static lv_obj_t * helm_climb_lab_at(lv_obj_t * parent, const lv_font_t * font,
    uint32_t color, const char * txt, int32_t x, int32_t y, int32_t w,
    lv_text_align_t align)
{
    lv_obj_t * lab = helm_lab(parent, font, color, txt);

    lv_obj_add_flag(lab, LV_OBJ_FLAG_FLOATING);
    if (w > 0) {
        lv_obj_set_width(lab, w);
        lv_obj_set_style_text_align(lab, align, 0);
    }
    lv_obj_set_pos(lab, x, y);
    return lab;
}

/** @brief 海拔页绝对坐标色块（2px 竖线 / 1px 横轴）。 */
static lv_obj_t * helm_climb_box_at(lv_obj_t * parent, int32_t x, int32_t y,
    int32_t w, int32_t h, uint32_t hex)
{
    lv_obj_t * box = lv_obj_create(parent);

    lv_obj_remove_style_all(box);
    lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(box, LV_OBJ_FLAG_FLOATING);
    lv_obj_set_pos(box, x, y);
    lv_obj_set_size(box, w, h);
    lv_obj_set_style_bg_color(box, helm_color(hex), 0);
    lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
    return box;
}
