2545	/**
2546	 * @brief 剖面覆盖距离（米），用于页头「前方 X km」与横轴两端。
2547	 * @return 导航：窗口剩余里程（(点数−1)×步长）；记录/空态：设计的名义 2 km。
2548	 */
2549	static uint32_t helm_climb_win_dist_m(void)
2550	{
2551	    if (s_win_n >= 2u && s_win_step_cm >= 1u) {
2552	        uint64_t cm = (uint64_t)(s_win_n - 1u) * (uint64_t)s_win_step_cm;
2553	        uint32_t m = (uint32_t)(cm / 100u);
2554	
2555	        return m > 0u ? m : 1u;
