2560	/**
2561	 * @brief 距离文案（10 m 精度；≥1 km 用 km，整数公里不带小数点）。
2562	 * @param buf 输出缓冲。
2563	 * @param cap 缓冲长度。
2564	 * @param m 距离（米）。
2565	 */
2566	static void helm_climb_fmt_dist(char * buf, size_t cap, uint32_t m)
2567	{
2568	    if (m < 1000u) {
2569	        lv_snprintf(buf, cap, "%u m", (unsigned)(((m + 5u) / 10u) * 10u));
2570	    } else if (m >= 10000u || (m % 100u) == 0u) {
2571	        lv_snprintf(buf, cap, "%u km", (unsigned)((m + 500u) / 1000u));
2572	    } else {
2573	        lv_snprintf(buf, cap, "%u.%u km", (unsigned)(m / 1000u),
2574	                    (unsigned)((m % 1000u) / 100u));
2575	    }
2576	}
