2580	/**
2581	 * @brief 用 `s_climb_eles` / `s_climb_zone` 的一段装配当前显示窗。
2582	 * @param start 窗口起点（全局采样下标）。
2583	 * @details 导航：从当前位置画到路线终点（前方剖面）；本机记录：整段（起点 0）。
2584	 *          分段色沿用 `s_climb_zone`（导航已按真实步长算过）；记录剖面没有
2585	 *          逐点距离，按名义 2 km / 59 段现算，和横轴口径一致。
2586	 */
2587	static void helm_climb_win_build(uint32_t start)
2588	{
2589	    const uint32_t n = s_sh.climb_n;
2590	    const uint32_t nominal_step_cm = (2000u * 100u) / (HELM_CLIMB_PROF_N - 1u);
2591	    uint32_t i;
2592	
2593	    if (n >= 2u) {
2594	        if (start > n - 2u) {
2595	            start = n - 2u;
2596	        }
2597	    } else {
2598	        start = 0;
2599	    }
2600	
2601	    s_win_start = (uint8_t)start;
2602	    s_win_n = (n >= 2u) ? (uint8_t)(n - start) : 0u;
2603	    s_win_step_cm = 0u;
2604	    s_win_peak = 0u;
2605	    s_win_min = 0;
2606	    s_win_max = 0;
2607	
2608	    if (s_win_n >= 2u) {
2609	        if (s_sh.climb_nav && s_climb_fp_total_cm != 0xffffffffu) {
2610	            uint32_t step = s_climb_fp_total_cm / (n - 1u);
2611	
2612	            s_win_step_cm = (step >= 1u) ? step : 0u;
2613	        }
2614	
2615	        s_win_min = s_climb_eles[start];
2616	        s_win_max = s_climb_eles[start];
2617	        for (i = 0; i < s_win_n; i++) {
2618	            const int16_t e = s_climb_eles[start + i];
2619	
2620	            s_win_eles[i] = e;
2621	            if (e < s_win_min) {
2622	                s_win_min = e;
2623	            }
2624	            if (e > s_win_max) {
2625	                s_win_max = e;
2626	                s_win_peak = (uint8_t)i;
2627	            }
2628	        }
2629	        for (i = 0; i + 1u < s_win_n; i++) {
2630	            s_win_zone[i] = s_sh.climb_nav
2631	                ? s_climb_zone[start + i]
2632	                : helm_climb_grade_zone(s_win_eles[i], s_win_eles[i + 1u],
2633	                                        nominal_step_cm);
2634	        }
2635	    }
2636	
2637	    helm_climb_canvas_repaint();
2638	}
2639	
2640	/**
2641	 * @brief 当前位置变化时换窗（窗口没变则什么都不做，绝不每拍重画）。
2642	 * @param start 新的窗口起点。
2643	 */
2644	static void helm_climb_win_apply(uint32_t start)
2645	{
2646	    const uint32_t n = s_sh.climb_n;
2647	
2648	    if (n < 2u) {
2649	        return;                 /* 空态已经画好：别每拍重画那条基线 */
2650	    }
2651	    if (start > n - 2u) {
2652	        start = n - 2u;
2653	    }
2654	    if (s_win_n >= 2u && (uint32_t)s_win_start == start &&
2655	        (uint32_t)s_win_n == n - start) {
2656	        return;
2657	    }
2658	    helm_climb_win_build(start);
2659	}
