2661	/**
2662	 * @brief 分配/复用 190×150 RGB565 画布缓冲。
2663	 * @return 画布可用则为 true。
2664	 * @details 缓冲在 PSRAM，固定尺寸只分配一次；画布对象可能刚被重建过
2665	 *          （换主题 = 整棵 shell 删掉再建），而缓冲是我们自己的内存 ⇒
2666	 *          尺寸没变也必须重新 `lv_canvas_set_buffer()`（幂等，无副作用）。
2667	 */
2668	static bool helm_climb_canvas_ensure(void)
2669	{
2670	    size_t bytes;
2671	
2672	    if (s_sh.climb_canvas == NULL) {
2673	        return false;
2674	    }
2675	    if (s_climb_cbuf == NULL) {
2676	        bytes = (size_t)lv_draw_buf_width_to_stride(HELM_CLIMB_CANVAS_W,
2677	                    LV_COLOR_FORMAT_RGB565) * (size_t)HELM_CLIMB_CANVAS_H;
2678	        s_climb_cbuf = vmap_malloc(bytes);
2679	        if (s_climb_cbuf == NULL) {
2680	            return false;
2681	        }
2682	        syslog(LOG_NOTICE, "[climb] canvas %dx%d buf=%uB\n",
2683	               HELM_CLIMB_CANVAS_W, HELM_CLIMB_CANVAS_H, (unsigned)bytes);
2684	    }
2685	    lv_canvas_set_buffer(s_sh.climb_canvas, s_climb_cbuf, HELM_CLIMB_CANVAS_W,
2686	                         HELM_CLIMB_CANVAS_H, LV_COLOR_FORMAT_RGB565);
2687	    lv_obj_set_size(s_sh.climb_canvas, HELM_CLIMB_CANVAS_W,
2688	                    HELM_CLIMB_CANVAS_H);
2689	    return true;
2690	}
