2692	/**
2693	 * @brief 把当前窗口画进整页画布（有数据：网格 + 分段三角 + 2px 折线）。
2694	 * @details 只在剖面窗变化 / 换主题时调用，不做每帧重画。
2695	 *          空态只画一条基线，不画假曲线。
2696	 */
2697	static void helm_climb_canvas_repaint(void)
2698	{
2699	    const int32_t w = HELM_CLIMB_CANVAS_W;
2700	    const int32_t h = HELM_CLIMB_CANVAS_H;
2701	    const int32_t base = h - 1;
2702	    const int32_t top = 10;
2703	    const int32_t bot = base - 10;
2704	    lv_layer_t layer;
2705	    lv_draw_line_dsc_t ld;
2706	    int32_t k;
2707	
2708	    if (!helm_climb_canvas_ensure()) {
2709	        return;
2710	    }
2711	
2712	    lv_canvas_fill_bg(s_sh.climb_canvas, helm_color(HELM_COLOR_PAPER),
2713	                      LV_OPA_COVER);
2714	    lv_canvas_init_layer(s_sh.climb_canvas, &layer);
2715	    lv_draw_line_dsc_init(&ld);
2716	    ld.opa = LV_OPA_COVER;
2717	
2718	    if (s_win_n >= 2u) {
2719	        const int32_t mn = s_win_min;
2720	        int32_t mx = s_win_max;
2721	        const int32_t span = bot - top;
2722	        uint32_t i;
2723	
2724	        if (mx - mn < 1) {
2725	            mx = mn + 1;
2726	        }
2727	
2728	        /* 3 条横向细网格线（card 色）：1/4、1/2、3/4。 */
2729	        ld.color = helm_color(HELM_COLOR_TRACK);
2730	        ld.width = 1;
2731	        for (k = 1; k <= 3; k++) {
2732	            ld.p1.x = 0;
2733	            ld.p1.y = top + span * k / 4;
2734	            ld.p2.x = w - 1;
2735	            ld.p2.y = ld.p1.y;
2736	            lv_draw_line(&layer, &ld);
2737	        }
2738	
2739	        for (i = 0; i + 1u < s_win_n; i++) {
2740	            const int32_t den = mx - mn;
2741	            const int32_t x1 = (int32_t)((uint32_t)i * (uint32_t)(w - 1) /
2742	                                         (uint32_t)(s_win_n - 1u));
2743	            const int32_t x2 = (int32_t)((uint32_t)(i + 1u) * (uint32_t)(w - 1) /
2744	                                         (uint32_t)(s_win_n - 1u));
2745	            const int32_t y1 = bot -
2746	                (int32_t)((((int32_t)s_win_eles[i] - mn) * span * 2 + den) /
2747	                          (2 * den));
2748	            const int32_t y2 = bot -
2749	                (int32_t)((((int32_t)s_win_eles[i + 1u] - mn) * span * 2 + den) /
2750	                          (2 * den));
2751	            lv_point_precise_t p1;
2752	            lv_point_precise_t p2;
2753	            const uint8_t z = s_win_zone[i];
2754	
2755	            p1.x = x1;
2756	            p1.y = y1;
2757	            p2.x = x2;
2758	            p2.y = y2;
2759	            helm_climb_paint_seg(&layer, p1, p2, base,
2760	                helm_color_snap(helm_climb_zone_fill(z)),
2761	                helm_color(helm_climb_zone_ink(z)), 2);
2762	        }
2763	    } else {
2764	        /* 空态：只有基线（当前位置竖线是页面对象，不画进画布）。 */
2765	        ld.color = helm_color(HELM_COLOR_HAIR);
2766	        ld.width = 1;
2767	        ld.p1.x = 0;
2768	        ld.p1.y = base;
2769	        ld.p2.x = w - 1;
2770	        ld.p2.y = base;
2771	        lv_draw_line(&layer, &ld);
2772	    }
2773	
2774	    lv_canvas_finish_layer(s_sh.climb_canvas, &layer);
2775	    lv_obj_invalidate(s_sh.climb_canvas);
2776	}
