2812	/**

2812	/**
2813	 * @brief 刷页头 / 轴标签 / 三统计 / 尾行文案。
2814	 * @param rt 当前骑行快照，可 NULL。
2815	 * @details 坡度取 `rt->grade_pct`（一位小数），累计爬升取 `rt->gain_m`，
2816	 *          最高点取当前窗口最大值；没有剖面时最高点与尾行给 `--` / 隐藏。
2817	 */
2818	static void helm_climb_labels_refresh(const bicycle_runtime_t * rt)
2819	{
2820	    const bool have = (s_win_n >= 2u);
2821	    const uint32_t dist_m = helm_climb_win_dist_m();
2822	    char buf[40];
2823	    char buf2[48];
2824	
2825	    /* 页头右：前方 X km */
2826	    helm_climb_fmt_dist(buf, sizeof(buf), dist_m);
2827	    lv_snprintf(buf2, sizeof(buf2), "前方 %s", buf);
2828	    helm_label_set(s_sh.climb_head_r, buf2);
2829	
2830	    /* 海拔 m / min–max m（右对齐到 216）。 */
2831	    if (have) {
2832	        lv_snprintf(buf, sizeof(buf), "%d–%d m",
2833	                    (int)s_win_min, (int)s_win_max);
2834	        helm_label_set(s_sh.climb_range, buf);
2835	    } else {
2836	        helm_label_set(s_sh.climb_range, "--");
2837	    }
2838	
2839	    /* 横轴：0 / 半程 / 全程。 */
2840	    helm_climb_fmt_dist(buf, sizeof(buf), dist_m / 2u);
2841	    helm_label_set(s_sh.climb_xlab[1], buf);
2842	    helm_climb_fmt_dist(buf, sizeof(buf), dist_m);
2843	    helm_label_set(s_sh.climb_xlab[2], buf);
2844	
2845	    /* 当前坡度：一位小数（%）。 */
2846	    if (rt != NULL) {
2847	        const int g10 = (int)(rt->grade_pct * 10.0f +
2848	                              (rt->grade_pct >= 0.0f ? 0.5f : -0.5f));
2849	
2850	        if (g10 < 0) {
2851	            lv_snprintf(buf, sizeof(buf), "-%d.%d", -g10 / 10, -g10 % 10);
2852	        } else {
2853	            lv_snprintf(buf, sizeof(buf), "%d.%d", g10 / 10, g10 % 10);
2854	        }
2855	        helm_climb_stat_set(0, buf);
2856	    } else {
2857	        helm_climb_stat_set(0, "--");
2858	    }
2859	
2860	    /* 累计爬升（米，四舍五入到整数）。 */
2861	    if (rt != NULL) {
2862	        lv_snprintf(buf, sizeof(buf), "%d", (int)(rt->gain_m + 0.5f));
2863	        helm_climb_stat_set(1, buf);
2864	    } else {
2865	        helm_climb_stat_set(1, "--");
2866	    }
2867	
2868	    /* 最高点（当前窗口最大值）。 */
2869	    if (have) {
2870	        lv_snprintf(buf, sizeof(buf), "%d", (int)s_win_max);
2871	        helm_climb_stat_set(2, buf);
2872	    } else {
2873	        helm_climb_stat_set(2, "--");
2874	    }
2875	
2876	    /* 尾行：最高点在前方 X km（没有逐点距离就整行隐藏）。 */
2877	    if (have && helm_climb_win_step_cm() >= 1u) {
2878	        uint64_t cm = (uint64_t)s_win_peak * (uint64_t)helm_climb_win_step_cm();
2879	        uint32_t m = (uint32_t)(cm / 100u);
2880	
2881	        lv_snprintf(buf, sizeof(buf), "最高点在前方 %u.%u km",
2882	                    (unsigned)(m / 1000u), (unsigned)((m % 1000u) / 100u));
2883	        helm_label_set(s_sh.climb_peak, buf);
2884	        lv_obj_remove_flag(s_sh.climb_peak, LV_OBJ_FLAG_HIDDEN);
2885	    } else if (s_sh.climb_peak != NULL) {
2886	        lv_obj_add_flag(s_sh.climb_peak, LV_OBJ_FLAG_HIDDEN);
2887	    }
2888	}
