2890	/**
2891	 * @brief 路线或近 30 分钟记录变化时重载海拔剖面。
2892	 * @details 数据链与老页完全一致：导航走 `map_page_nav_profile_ele()`（按总里程
2893	 *          均匀 60 点 + 当前位置），未导航走 `s_rec_ele[]`（30 分钟记录）。
2894	 *          导航分段按真实步长算 `s_climb_zone`，骑行中不重算；换路线 / 换
2895	 *          窗口时才重画 190×150 画布。
2896	 */
2897	static void helm_climb_profile_reload(void)
2898	{
2899	    int16_t eles[HELM_CLIMB_PROF_N];
2900	    uint32_t n = 0;
2901	    uint32_t now_idx = LV_CHART_POINT_NONE;
2902	    uint32_t i;
2903	    bool nav;
2904	    int16_t last = 0;
2905	    bool have = false;
2906	    uint32_t fp_pts = 0;
2907	    uint32_t fp_total_cm = 0;
2908	
