static void tour_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[tour] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

