```
static void helm_climb_zone_run_build(const int16_t * eles, uint8_t n,
    uint32_t step_cm, uint8_t * zone, uint8_t * runs, uint8_t * minrun)
{
    uint8_t raw[HELM_CLIMB_PROF_N];
    uint8_t nseg = (n >= 2u) ? (uint8_t)(n - 1u) : 0u;
    uint8_t i;
    uint8_t z;
    bool changed;

    *runs = 0;
    *minrun = 0;
    if (nseg == 0u) return;
    if (step_cm < 1u) {
        // 没有距离：全部按平坦处理（但仍要画）
        for (i = 0; i < nseg; i++) zone[i] = 0;
        *runs = 1; *minrun = nseg; return;
    }
    for (i = 0; i < nseg; i++) {
        raw[i] = helm_climb_grade_zone(eles[i], eles[i+1], step_cm);
    }
    z = raw[0];
    zone[0] = z;
    for (i = 1; i < nseg; i++) {
        if (raw[i] != z && (i + 1u >= nseg || raw[i+1] == raw[i])) {
            z = raw[i];
        }
        zone[i] = z;
    }
    // 合并 <3 段的短带：
    for (;;) {
        uint8_t i0 = 0;
        bool merged = false;
        while (i0 < nseg) {
            uint8_t i1 = i0;
            while (i1 + 1u < nseg && zone[i1+1] == zone[i0]) i1++;
            // run [i0..i1]
            if ((uint8_t)(i1 - i0 + 1u) < 3u && nseg >= 3u) {
                uint8_t repl;
                if (i0 == 0u) {
                    // 用下一段的颜色（下一段存在，因为总段数>=3）
                    repl = zone[i1 + 1u];
                } else {
                    repl = zone[i0 - 1u];
                }
                for (uint8_t k = i0; k <= i1; k++) zone[k] = repl;
                merged = true;
                break; // 重新扫（可能又产生更短/相邻合并）
            }
            i0 = (uint8_t)(i1 + 1u);
        }
        if (!merged) break;
    }
    // 统计
    {
        uint8_t i0 = 0;
        while (i0 < nseg) {
            uint8_t i1 = i0;
            uint8_t len;
            while (i1 + 1u < nseg && zone[i1+1] == zone[i0]) i1++;
            len = (uint8_t)(i1 - i0 + 1u);
            (*runs)++;
            if (*minrun == 0u || len < *minrun) *minrun = len;
            i0 = (uint8_t)(i1 + 1u);
        }
    }
}
```
Careful: merging the *first* short run into the next run's color could make the first run and the next run the same color as the second run... If i0==0 and the next run is also short, repeated merging handles it. If i0==0 and the next run is the only other run and short (<3), merging sets zone[0..i1] = next color; then the whole array is one color with nseg possibly ≥3 → runs=1, minrun=nseg. That's acceptable (a single flat-ish profile). But the assertion runs>=3 would fail for such data; our GPX has variation.

