/**
 * @brief 把窗口坡度切成**连续 zone 带**（2 段滞回 + 最短 3 段）。
 * @param eles 平滑后的窗口海拔（米）。
 * @param n 点数。
 * @param step_cm 每段水平距离（厘米）；记录剖面传名义步长。
 * @param[out] zone 每段 zone（n−1 个）。
 * @param[out] runs 连续带数量。
 * @param[out] minrun 最短带（段）。
 * @details ① 先按阈值取原始档；
 *          ② 滞回：换区必须**连续 2 段**同档才成立（1 段的毛刺被吸收）；
 *          ③ 再把短于 3 段的带并到相邻带（首带并到后一段，其余并到前一段），
 *             避免 1~2 段宽的颜色竖条 —— 观感是参照图的连续色带，不是条形码。
 */
static void helm_climb_zone_run_build(const int16_t * eles, uint8_t n,
    uint32_t step_cm, uint8_t * zone, uint8_t * runs, uint8_t * minrun)
{
    uint8_t raw[HELM_CLIMB_PROF_N];
    uint8_t nseg = (n >= 2u) ? (uint8_t)(n - 1u) : 0u;
    uint8_t i;

    *runs = 0;
    *minrun = 0;
    if (nseg == 0u) {
        return;
    }

    for (i = 0; i < nseg; i++) {
        raw[i] = helm_climb_grade_zone(eles[i], eles[i + 1u], step_cm);
    }

    /* 滞回：连续 2 段成立才换区。 */
    zone[0] = raw[0];
    for (i = 1; i < nseg; i++) {
        if (raw[i] != zone[i - 1u] &&
            (i + 1u >= nseg || raw[i + 1u] == raw[i])) {
            zone[i] = raw[i];
        } else {
            zone[i] = zone[i - 1u];
        }
    }

    /* 短带合并：< 3 段的带并入相邻带（首带取后一段，其余取前一段）。 */
    for (;;) {
        uint8_t i0 = 0;
        bool merged = false;

        while (i0 < nseg) {
            uint8_t i1 = i0;
            uint8_t repl;

            while (i1 + 1u < nseg && zone[i1 + 1u] == zone[i0]) {
                i1++;
            }
            if (nseg < 3u) {
                break;
            }
            if ((uint8_t)(i1 - i0 + 1u) < 3u) {
                repl = (i0 == 0u) ? zone[i1 + 1u] : zone[i0 - 1u];
                while (i0 <= i1) {
                    zone[i0++] = repl;
                }
                merged = true;
                break;
            }
            i0 = (uint8_t)(i1 + 1u);
        }
        if (!merged) {
            break;
        }
    }

    /* 统计连续带数量与最短带。 */
    i = 0;
    while (i < nseg) {
        uint8_t i1 = i;
        uint8_t len;

        while (i1 + 1u < nseg && zone[i1 + 1u] == zone[i]) {
            i1++;
        }
        len = (uint8_t)(i1 - i + 1u);
        (*runs)++;
        if (*minrun == 0u || len < *minrun) {
            *minrun = len;
        }
        i = (uint8_t)(i1 + 1u);
    }
}
