 */
static void helm_climb_win_build(uint32_t start)
{
    const uint32_t n = s_sh.climb_n;
    const uint32_t nominal_step_cm = (2000u * 100u) / (HELM_CLIMB_PROF_N - 1u);
    uint32_t i;

