    }

    s_win_start = (uint8_t)start;
    s_win_n = (n >= 2u) ? (uint8_t)(n - start) : 0u;
    s_win_step_cm = 0u;
    s_win_peak = 0u;
    s_win_min = 0;
    s_win_max = 0;

    if (s_win_n >= 2u) {
        if (s_sh.climb_nav && s_climb_fp_total_cm != 0xffffffffu) {
            uint32_t step = s_climb_fp_total_cm / (n - 1u);

            s_win_step_cm = (step >= 1u) ? step : 0u;
        }

        s_win_min = s_climb_eles[start];
        s_win_max = s_climb_eles[start];
        for (i = 0; i < s_win_n; i++) {
            const int16_t e = s_climb_eles[start + i];

            s_win_eles[i] = e;
            if (e < s_win_min) {
                s_win_min = e;
